	allegiance = "A Milícia Popular",
	aliases = { "Stoutmantle", "Lorde Stoutmantle" },
	sections = {
		{
			title = "Resumo",
			text = [=[Gryan Stoutmantle lidera a Milícia Popular a partir da torre de vigia do {link:sentinel-hill}Morro da Sentinela{/link}. Voltou das terras maculadas de {link:lordaeron}Lordaeron{/link} e encontrou sua terra natal tomada por ladrões e esquecida por seu rei. Não esperou por ajuda. Reuniu os fazendeiros que não queriam partir, deu-lhes armas e os fez jurar defender {link:westfall}Cerro Oeste{/link} em nome da {link:holy-light}Luz Sagrada{/link}.]=],
