Translate("ptBR", "harvest-golems", {
	title = "Golens de Colheita",
	aliases = { "golens de colheita", "Golem de Colheita", "golem de colheita", "Vigias da Colheita", "Vigia da Colheita", "máquinas de colheita" },
	sections = {
		{
			title = "Resumo",
			text = [=[Golens de colheita são grandes máquinas de ferro construídas para trabalhar os campos de {link:westfall}Cerro Oeste{/link}. Foram feitos para ceifar, semear e vigiar as plantações. Agora percorrem as fazendas abandonadas sem senhor e expulsam qualquer um que se aproxime, como se os próprios fazendeiros fossem pragas a serem limpas das fileiras.]=],
		},
		{
			title = "Tipos",
			text = [=[• {b}Golens de colheita enferrujados{/b} e {b}golens de colheita{/b} são os menores e mais fracos deles.
• {b}Vigias da Colheita{/b} montam guarda sobre os campos, como o nome sugere.
• {b}Ceifadores da Colheita{/b} são os maiores e mais perigosos. Percorrem os campos queimados do {link:the-dead-acre}Alqueire Morto{/link}.
• {b}O Foe Reaper 4000{/b} é uma máquina única, muito mais forte que as outras, que percorre os campos das planícies do oeste.]=],
		},
		{
			title = "Nestes Dias",
			text = [=[Nenhum fazendeiro sabe dizer ao certo como as máquinas se descontrolaram. Muitos em {link:westfall}Cerro Oeste{/link} culpam a {link:defias-brotherhood}Irmandade Défias{/link}, cujos aliados goblins constroem e comandam golens nas profundezas das {link:the-deadmines}Minas Mortas{/link}. O {link:gnomes}gnomo{/link} {link:ozwin-ironsprocket}Ozwin Ironsprocket{/link} estudou suas peças e aprendeu a sobrepor seu comando, ainda que só por um momento. O fantasma do {link:westfall-lighthouse}Farol de Cerro Oeste{/link} alimenta sua chama com o óleo drenado de suas juntas. O {link:farmer-saldean}Fazendeiro Saldean{/link} só quer vê-las longe.]=],
		},
	},
})
